def starting_uses_and_years(apps, schema_editor):
    """Adds the starting list of uses, matches existing properties to it by name, and fills in the year built."""
    from apps.properties.uses import STARTING_USES, year_from

    PropertyUse = apps.get_model("properties", "PropertyUse")
    Property = apps.get_model("properties", "Property")
    by_name = {}
    for i, (name, standard) in enumerate(STARTING_USES, start=1):
        use, _created = PropertyUse.objects.get_or_create(
            name=name, defaults={"standard_usage": standard, "order": i * 10})
        by_name[name.lower()] = use
    for prop in Property.objects.exclude(use_description="").filter(use_type__isnull=True):
        use = by_name.get(prop.use_description.strip().lower())
        if use:
            Property.objects.filter(pk=prop.pk).update(use_type=use)
    for prop in Property.objects.exclude(built="").filter(built_year__isnull=True):
        year = year_from(prop.built)
        if year:
            Property.objects.filter(pk=prop.pk).update(built_year=year)


